  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "The aim of this systematic review was to identify socio-economic, demographic and obstetric factors predictive of maternal near-miss (MNM)in women aged 15-49 years in Africa.",
      "reason": "The objective is explicitly stated in the Objectives section, restated in the Background (text_3), and framed as a review question (text_9). A relevant question-formulation framework (PECO) is explicitly applied in text_10, defining Population, Exposure, Comparison, and Outcome."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_10",
      "quote": "This review used the PECO (Population, Exposure, Comparison and Outcomes) approach to research",
      "reason": "This is a review of determinants/predictors of maternal near-miss, not a review of intervention effects, so PICO-based planned comparisons do not apply; the authors appropriately used PECO instead."
    }
  ],
  "confidence": 92
}

